window.HERO_IMAGE='https://images.unsplash.com/photo-1690626826406-c2fc0d344551?fm=jpg&ixid=M3wxMjA3fDB8MHxwaG90by1yZWxhdGVkfDEzfHx8ZW58MHx8fHx8&ixlib=rb-4.1.0&q=60&w=3000';
const posts = [
{id:'mountains',category:'旅行',date:'2026.09.21',time:'4 分钟',title:'在山与湖之间，把日子慢下来',excerpt:'不赶路，不打卡。沿着湖边走一段，听风经过树梢，也听见久违的自己。',place:'山野',body:[['没有计划的清晨','出发前，我在笔记本上写下很多想去的地方。真正到了湖边，却只想把那张清单收起来。清晨的水面很安静，远处的山还藏在薄雾里，一切都没有催促我的意思。','我沿着小路慢慢走，路过一张空长椅，就坐下来。带来的书只翻了两页，更多的时候在看光线从山的另一侧一点点移过来。'],['把时间还给自己','旅行最舒服的时刻，常常不在计划里面。可能是一杯刚泡好的茶，一条临时拐进去的小路，也可能是忽然发现，自己已经很久没有看过这么完整的一片天空。','午后起了风，水面有了细碎的光。我没有急着拍照，只站在那里看了一会儿。原来留住一个瞬间，不一定需要把它装进相机。'],['带回去的东西','回来的行李没有多出多少东西，笔记本倒是写满了几页。我想记住的不是走过了多少地方，而是某一天，终于允许自己什么都不做。','下一次出发，或许仍然没有特别的目的地。只要能走近自然，让脚步比平时慢一些，就很好。']]},
{id:'weekend',category:'日常',date:'2026.09.14',time:'3 分钟',title:'一个人的周末，也可以很丰盛',excerpt:'逛早市、买花、做一顿不慌不忙的饭。普通日子里的小事，拼起来就是生活。',body:[['从早市开始','周末不设闹钟，醒来后给自己倒一杯水，再慢慢走去附近的早市。摊位上有刚摆好的水果，空气里是面包和热豆浆的气味。','我买了几样蔬菜，也带回一小束花。它们不是什么特别的品种，放进玻璃瓶以后，却让整张桌子都明亮起来。'],['认真吃一顿饭','回家后打开窗户，洗菜、煮饭，放一张熟悉的唱片。没有复杂的菜谱，只做自己喜欢的口味。饭做好时，阳光刚好落在桌边。','一个人的周末不必被安排得很满。留出一点空白，才会发现自己真正想做的事情。'],['小小的满足','下午读书，傍晚散步，路过熟悉的街口时买一个面包。一天就这样过去了，没有大事发生，却觉得心里很充实。']]},
{id:'old-town',category:'旅行',date:'2026.08.30',time:'3 分钟',title:'迷路的时候，遇见一座城',excerpt:'比起地图上标好的目的地，我更喜欢转角的小店、晾晒的衣服，和巷子里慢慢展开的生活。',body:[['拐进一条小巷','原本只是想找一间咖啡店，走过路口时却被一扇旧窗吸引。我转进旁边的小巷，地图上的蓝点慢慢偏离了路线。','沿街的房子并不整齐。有人的窗台上种着薄荷，有人把椅子搬到了门口。一只猫伏在台阶上，看了我一眼，又继续睡了。'],['城市的另一面','我越来越喜欢在旅行时留半天给步行，不设终点，也不计算步数。那些没有被写进攻略的地方，反而让我觉得真正认识了这座城。','后来在一家小店坐下，点了杯茶。老板说，午后的这条街一直很安静。我就在那里待到了太阳往西边走。'],['不必每次都找到答案','最后没找到最初的咖啡店，却带回了很多细碎的画面。偶尔走错路，也可以是旅行送来的礼物。']]},
{id:'little-light',category:'日常',date:'2026.08.18',time:'2 分钟',title:'收集生活里，那些很小的光',excerpt:'窗边的晨光、读到的一句话、散步时的晚霞。幸福有时候，只需要多看一眼。',body:[['一份很小的清单','最近开始在睡前记下当天喜欢的三件小事。不必特别，也不必有意义。今天的第一件，是早餐时听到窗外的鸟叫。','第二件，是午后读到一句让人停下来的话。第三件，是回家时天边很淡的粉色。它们都很短暂，却确实让这一天变得不同。'],['练习发现','记录久了才发现，生活并不是缺少值得开心的事情，只是忙起来的时候容易错过。把注意力放回身边，很多平凡的东西都会重新清晰。','我想继续保持这个习惯。不是为了让每一天都完美，而是为了记得，每一天也有值得留下的部分。']]}
];
const app=document.querySelector('#app');let filter='全部';
function list(items){return items.map((p,i)=>`<article class="post"><span class="post-num">${String(i+1).padStart(2,'0')}</span><div><div class="meta"><span class="tag">${p.category}</span><span>·</span><time>${p.date}</time><span>${p.time}</span></div><h3><a href="#post/${p.id}">${p.title}</a></h3><p>${p.excerpt}</p></div></article>`).join('')}
function render(){const hash=location.hash.slice(1);document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(hash==='about'?'about':hash==='archive'?'archive':'home')));if(hash.startsWith('post/')){const p=posts.find(p=>p.id===hash.split('/')[1]);if(!p){app.innerHTML='<div class="page-heading"><h1>这篇手记暂时不在这里</h1><a href="#">返回首页</a></div>';return}document.title=p.title+' · 途中';app.innerHTML=`<article class="article"><a class="back" href="#">返回全部手记</a><div class="meta"><span class="tag">${p.category}</span><time>${p.date}</time><span>阅读约 ${p.time}</span></div><h1>${p.title}</h1><p class="lead">${p.excerpt}</p><div class="body">${p.body.map(([h,...ps])=>`<h2>${h}</h2>${ps.map(t=>`<p>${t}</p>`).join('')}`).join('')}</div><div class="article-end">谢谢你读到这里。愿我们都能在自己的节奏里，好好生活。</div></article>`;return}document.title='途中 · 生活与旅行手记';if(hash==='about'){app.innerHTML=`<section class="about"><div class="page-heading"><span class="eyebrow">A LITTLE ABOUT ME</span><h1>你好，欢迎来到途中。</h1><p>一个喜欢走走停停，也喜欢认真生活的人。</p></div><div class="stamp">途</div><p>我喜欢在陌生的城市散步，在路边的小店坐一会儿，也喜欢在普通的周末买菜、看书、晒太阳。</p><p>「途中」是我留给生活的一本笔记。这里记录旅途中的风景，也收藏那些微小、安静，却让人觉得值得的日常。</p><h2>为什么写下来</h2><p>记忆会变淡，文字可以让它停留得久一点。我希望多年以后再读这些记录，还能想起当时的风、光线，以及那一刻的心情。</p><h2>关于这本手记</h2><p>旅行，是走向更远的地方；日常，是看见身边的美好。不追求更新的频率，有想分享的事情，就在这里写一写。</p><a class="tiny-link" href="#">读读最近的手记</a></section>`;return}if(hash==='archive'){app.innerHTML=`<section class="archive"><div class="page-heading"><span class="eyebrow">THE JOURNAL ARCHIVE</span><h1>时光有迹。</h1><p>把走过的路，过过的日子，一篇篇收好。</p></div><div class="section-top"><h2>2026</h2><span class="meta">${posts.length} 篇手记</span></div>${list(posts)}</section>`;return}app.innerHTML=`<section class="intro"><div><span class="eyebrow">A PERSONAL JOURNAL · SINCE 2026</span><h1>走走停停，都是生活。</h1></div><p>记录途中的风景，<br>也收藏普通日子里的光。</p></section><a class="hero" href="#post/mountains"><img id="hero-photo" alt="山峦与湖泊构成的宁静风景"><div class="hero-content"><span class="eyebrow">精选手记 / 旅行</span><h2>在山与湖之间，<br>把日子慢下来</h2><p>不赶路，不打卡。让风景留在眼里，让时间回到自己手中。</p><span class="read">读这篇手记</span></div><span class="hero-number">01 / JOURNAL</span></a><div class="content-grid"><section><div class="section-top"><h2>最近的手记</h2><div class="filters" aria-label="文章分类">${['全部','旅行','日常'].map(c=>`<button type="button" class="${c===filter?'active':''}" aria-pressed="${c===filter}" data-filter="${c}">${c}</button>`).join('')}</div></div><div id="post-list">${list(posts.filter(p=>filter==='全部'||p.category===filter))}</div></section><aside class="sidebar"><section class="aside-block"><span class="eyebrow">HELLO, STRANGER</span><h3>一个记录生活的人。</h3><p>喜欢山野，也喜欢街巷。<br>相信每段旅程都有回响，<br>每个日常都值得珍藏。</p><a class="tiny-link" href="#about">多了解我一点</a></section><section class="aside-block"><span class="eyebrow">THE LITTLE COLLECTION</span><h3>手记里的片段</h3><a href="#post/mountains" class="location"><span>山野与湖泊</span><span>01</span></a><a href="#post/old-town" class="location"><span>城市与街巷</span><span>02</span></a><a href="#post/weekend" class="location"><span>日常与微光</span><span>03</span></a></section><section class="aside-block"><p class="quote">“把日子过成自己<br>喜欢的样子，<br>慢一点也没关系。”</p><span class="eyebrow">NOTE TO SELF</span></section></aside></div>`;if(window.HERO_IMAGE)document.querySelector('#hero-photo').src=window.HERO_IMAGE;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;const y=scrollY;render();scrollTo(0,y)})}
window.addEventListener('hashchange',()=>{render();scrollTo(0,0)});render();
